static int convert(unsigned long int value, char *buf, size_t size, int base, int caps)
{
    const char *digits = caps ? "0123456789ABCDEF" : "0123456789abcdef";
    size_t pos = 0;
    do
    {
        buf[pos++] = digits[value % base];
        value /= base;
    } while (value != 0 && pos < size);
    return (int)pos;
}

