static unsigned long int cast(double value)
{
    unsigned long int result;
    if (value >= (0x7fffffffffffffffL * 2UL + 1UL))
        return (0x7fffffffffffffffL * 2UL + 1UL);
    result = value;
    return (result <= value) ? result : result - 1;
}

